-- Resources content for the phase E follow-up (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- Follows 20261113120000. The three guides that said the website pages were still to come are updated in place (a guide an editor has
-- changed since is flagged for review and not overwritten), and one release note says what is new: the facilitator's email and link, the
-- organizer's link, the listed events on the website's listening page, and the purge of facilitators' emails.
--
-- Station-neutral on purpose: a guide is kept data, and the fresh-install check fails on any kept guide that names a station.

select private.rc_release_guide(
  p_slug => 'audience-listening-campaigns-events-and-table-cards',
  p_tool_key => 'audience-listening',
  p_title => 'Campaigns, events and table cards',
  p_summary => 'Set up a season of listening, schedule events inside it, get a public event listed, and print the cards for its tables.',
  p_screen_keys => array['audience-listening.campaigns', 'audience-listening.campaign', 'audience-listening.events', 'audience-listening.event'],
  p_sort_order => 50,
  p_version_note => 'Organizer links, the hub list and what to test before a real session',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"campaign","marks":[{"type":"bold"}]},{"type":"text","text":" is a season of listening: one question, the prompts a table is walked through, a list of tags, and the dates it runs. An "},{"type":"text","text":"event","marks":[{"type":"bold"}]},{"type":"text","text":" is a session in a place at a time inside that season, and a "},{"type":"text","text":"table","marks":[{"type":"bold"}]},{"type":"text","text":" is one conversation at it. A kitchen table is an event with one table. Campaigns and Events sit beside Queries in the section's navigation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Campaigns"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose Campaigns, then New campaign. Give it a title, the question it asks, an introduction for the website, and the dates it opens and closes. It starts as a draft and nothing is public."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prompts and tags","marks":[{"type":"bold"}]},{"type":"text","text":" holds what a table is asked, in order, and the words a facilitator picks from when they mark a line as what mattered. Each prompt can carry a hint for the facilitator and a suggested time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the campaign once it has at least one prompt. Closing it also closes the query linked to it under Settings, so a question is not still taking answers after the season is over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a draft with no events can be deleted. A campaign that ran is closed and then archived, so what it heard stays on the record."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Add an event from its campaign's Events tab. Its start has to fall inside the campaign's dates; the Portal refuses it otherwise. Times are the station's local time."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"private","marks":[{"type":"bold"}]},{"type":"text","text":" event is never listed. The organizer shares it themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A listed public event that is still to come appears on the website's listening page under "},{"type":"text","text":"Join a listening session","marks":[{"type":"bold"}]},{"type":"text","text":", with its seats left. It leaves that list once it has ended or been taken off the website."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"public","marks":[{"type":"bold"}]},{"type":"text","text":" event needs an address and a number of seats, and can be listed on the website only after a coordinator approves it. Anyone can ask for a review. A coordinator approves it after ticking each item on the checklist (a public place, an identified organizer with a verified email, a date inside the campaign, accessibility details, not a fundraiser or campaign event, and the consent reading acknowledged), or declines it with a reason the organizer is told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If anyone other than a coordinator changes what the public sees on a listed event (its title, time, place, address or seats), it goes back to review. Making an event private takes it off the website at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approving, declining and taking an event off the website are recorded with who did them. The Events page can show only those waiting for review, and the count appears beside Events in the navigation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tables and cards"}]},{"type":"paragraph","content":[{"type":"text","text":"On an event, add the tables it needs. "},{"type":"text","text":"Make new links and cards for every table","marks":[{"type":"bold"}]},{"type":"text","text":" gives each table a single-use link and draws a card for it with a QR code, to print at 7 by 5 inches, one to a page."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A link is shown once, on that page. The Portal keeps only a scrambled copy, so a card cannot be reprinted later. To get a card back, make a new link."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new link replaces the old one. A card printed earlier, and any phone using it, stops working. If one phone is lost or cannot scan, make a new link for that table alone and read it out or show it to the person."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card also carries a second QR code, for leaving a contact card. It is made together with the links when you make them for every table, and not when you replace one table's link, so a new link in the middle of a night does not break the card people are already using."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Making links needs the website's address to be set on the server. If it is not, the page says so instead of printing a card that goes nowhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opening a card's link does not use it up; the table's phone does that when its facilitator presses the button. A card that was only scanned to see where it goes still works."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that has not started can be removed. One that has been agreed to or recorded is kept."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Seats"}]},{"type":"paragraph","content":[{"type":"text","text":"A public event shows the seats people have saved, each with a name and an email given for that event only. Remove one to free the seat and delete the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The organizer's room"}]},{"type":"paragraph","content":[{"type":"text","text":"A person running an event can follow where every table is from the website, move the room on to the next prompt, call the last five minutes and clear a table's request for a hand. They never see what anyone says. They need an account on the website, and a link from you."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A coordinator chooses "},{"type":"text","text":"Make an organizer link","marks":[{"type":"bold"}]},{"type":"text","text":" on the event. The link is shown once, and the Portal keeps only a scrambled copy. Give it to the person running the event."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whoever opens it signed in to the website and presses the button becomes the organizer, so give it to one person. Making a new link lets a different account take over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An event with no organizer account is run from Tonight in the Portal."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The website pages are built: the card's link, the table's phone, the facilitator's after-page, the contact card, a public event's page and the organizer's room. Before the first real session, make links, print one card and run one table on a real phone, with the screen locked for a few minutes, so you know that phone records and sends. That test uses the table's link up, so make a new link for the table before the real night."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing on these pages is public until you say so, and a public event is never listed without a coordinator."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-consent-wording-and-tables',
  p_tool_key => 'audience-listening',
  p_title => 'Consent wording and what happens at a table',
  p_summary => 'Write the words a facilitator reads aloud, and see how a table agrees, records and finishes.',
  p_screen_keys => array['audience-listening.consent'],
  p_sort_order => 60,
  p_version_note => 'The facilitator gives an email when the table agrees',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before a table records, its facilitator reads a short agreement aloud and taps to say the whole table agrees. This page holds those words. Open it from "},{"type":"text","text":"Consent wording","marks":[{"type":"bold"}]},{"type":"text","text":" on the Campaigns page."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The wording"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The words are kept as numbered versions. A version is never edited: a change is a new version, so each table's agreement points at the exact words its facilitator read."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a coordinator can add a version. Settle the wording with the University's counsel and the records officer before the first real session."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"With no wording saved, no table can open, because its page would have nothing to read aloud. The event page says so."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens at a table"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card's QR code opens the table's single-use link. Opening it starts a session for that phone. A second phone using the same link is turned away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The facilitator reads the wording and taps to agree. The Portal records when, the wording version they were shown, their first name if they gave one, and their email, which they must give so the Portal can send them one link afterwards. Nothing records before this."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The phone records in segments of at most five minutes and uploads each as it goes, so a dropped connection picks up where it left off. When the table ends, the conversation is complete once every segment has arrived."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the event page each table shows when it agreed, to which version, who facilitated, whether it asked for a hand, and how much has been recorded. If a phone is lost, make a new link for that table: it ends the old session."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The website pages a card opens are built. Try one table on a real phone before the first real session."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After a table, see \"Tonight, tables after the session and purging\" for sending a recording to Sourcework, the facilitator's after-page and contact cards."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-tonight-tables-and-purging',
  p_tool_key => 'audience-listening',
  p_title => 'Tonight, tables after the session and purging',
  p_summary => 'Run an event, send a recording to Sourcework, review what the facilitator marked and the contact cards, and purge what is due.',
  p_screen_keys => array['audience-listening.tonight', 'audience-listening.table', 'audience-listening.purge'],
  p_sort_order => 70,
  p_version_note => 'The link for facilitators, and the purge clears emails',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three screens cover the session itself and what follows it: "},{"type":"text","text":"Tonight","marks":[{"type":"bold"}]},{"type":"text","text":" while an event runs, the "},{"type":"text","text":"Table","marks":[{"type":"bold"}]},{"type":"text","text":" page after it, and "},{"type":"text","text":"Purge","marks":[{"type":"bold"}]},{"type":"text","text":" for retention."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tonight"}]},{"type":"paragraph","content":[{"type":"text","text":"Open Tonight from an event. Keep it open for the session."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It checks in every 15 seconds. Tables are told that help is coming only while a screen like this is open; otherwise their phone says the request is flagged and, if it is urgent, to ask at the front."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn sound on","marks":[{"type":"bold"}]},{"type":"text","text":" so a new request for a hand makes a tone as well as a notice. Browsers only allow sound after you click, so it starts off."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that asks for a hand shows a badge. Choose \"Someone is on the way\" once it is dealt with."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move the room to a prompt, or call the last five minutes, which tables then see. A last call is made once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The After list shows where each table's recording has got to. Nothing reminds anyone to finish, because the Portal has no background jobs: look at it the next day for tables still marked Recording or Uploading."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After a table"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a table from its event. It shows when the table agreed, to which wording version, and how much was recorded."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once the table has ended and every segment has uploaded, choose Send to Sourcework. It needs access to Sourcework. The segments are joined into one recording and the transcript starts. The first table sent makes the season's Sourcework project; later tables become sources in it. The original segments are kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the transcript is ready, the facilitator's after-page shows only that table's lines. They name the voices by first name, mark the lines that mattered with a tag from the season's list, and send the conversation. Naming is optional. The Table page shows the transcript with the names and marks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Email the facilitator their link.","marks":[{"type":"bold"}]},{"type":"text","text":" The Table page shows the email they gave, and "},{"type":"text","text":"Email the link to the facilitator","marks":[{"type":"bold"}]},{"type":"text","text":" sends them a link to the after-page. "},{"type":"text","text":"A button under the tables on the event page"},{"type":"text","text":" reaches every table that has an email, a recording not yet sent to the station and no link yet. Nothing sends on its own, so press it once the transcripts are ready."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The link opens that table's page only, works for fourteen days and cannot record. A new link replaces the last, so sending again is how to recover from one that went astray. If the email cannot be sent (the server's email is not set up, for one) the page shows the link so you can hand it over yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A line that was marked keeps the words it had when it was marked, even if the recording is transcribed again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Contact cards"}]},{"type":"paragraph","content":[{"type":"text","text":"People at a table can scan the card's second QR code and leave a first name, a way to reach them, and three separate choices: may be contacted, may be named, keep anonymous. Naming and anonymous cannot both be chosen. All three start off."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Table page is the only place a card's contents appear. The facilitator sees how many were left, never what they say."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A person can say you may contact them and leave no way to reach them. The card is kept as they chose it and you are told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark a card as contacted once you have. Approving the use of a name is refused until you have, and for anyone who did not say they could be named."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deleting a card removes everything on it for good."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Purge"}]},{"type":"paragraph","content":[{"type":"text","text":"Purge lists what is due and lets a coordinator delete it. Nothing is purged on its own."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An unfinished submission, with its answers and audio, is due after 30 days untouched."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator never sent is due 30 days after its event ended, with its segments, voices, marks and contact cards. One that holds a card someone has already acted on, by contacting the person or approving their name, is kept, because that card is the record of what they agreed to. The Purge screen says how many are kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A facilitator's email and after-page link are cleared 30 days after the event, whether or not the conversation was sent. The Purge screen counts them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator sent is never purged here. Contact cards and unused raw audio follow the season's report date, which is not set up yet, so neither is due."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An event's organizer runs the room from the website, once a coordinator has given them a link from the event page. It shows where each table is, moves the room on and calls the last five minutes, and never shows what was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a mailbox is set up on the server, an email goes to it when someone asks to host a session. It says one is waiting and links to Host requests; it carries nothing the person wrote."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-13-audience-listening-facilitator-links-organizers',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-13',
  p_title => 'Facilitators get their link by email and organizers get a link of their own',
  p_guide_slugs => array['audience-listening-campaigns-events-and-table-cards', 'audience-listening-consent-wording-and-tables', 'audience-listening-tonight-tables-and-purging'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything a table needs on the night now works from a phone. A facilitator gives an email when the table agrees, and you email them a link to name the voices and mark what mattered once the transcript is ready; it works for fourteen days and cannot record. A coordinator can make a link that makes one account on the website the organizer of an event, and listed public events appear on the website's listening page. The purge also clears facilitators' emails after 30 days. Try one table on a real phone before the first real session."}]}]}$body$
);
